689: SysResult_t BSP_USB_CloseEp(uint8_t ep)
690: {
691:     HAL_StatusTypeDef status;
692:     USB_OTG_EPTypeDef *entry;
693:     SysResult_t result;
694:     if (!s_ready || !Usb_ValidEp(ep))
695:         return SYS_ERR_INVALID_ARG;
696:     if (s_bulk_fifo_owner != 0U) return SYS_ERR_BUSY;
697:     entry = Usb_PcdEp(ep);
698:     if (entry->maxpacket == 0U)
699:         return SYS_ERR_INVALID_STATE;
700:     //EP0由Core关闭，不经过仅供数据端点使用的Abort接口
701:     if ((ep & 0x0FU) == 0U)
702:     {
703:         uint32_t USBx_BASE = (uint32_t)s_pcd.Instance;
704:         uint32_t interrupt = (ep & 0x80U) != 0U ? 1U : (1UL << 16);
705: 
706:         //先屏蔽本方向，取消失败也不把旧完成交给后续事务
707:         USBx_DEVICE->DAINTMSK &= ~interrupt;
708:         if ((ep & 0x80U) != 0U)
709:             USBx_DEVICE->DIEPEMPMSK &= ~1UL;
710:         status = HAL_PCD_EP_Abort(&s_pcd, ep);
711:         if (status != HAL_OK)
712:             return Usb_HalResult(status);
713: 
714:         //IN只清TX0，OUT不清共享RX，避免影响其他端点
715:         if ((ep & 0x80U) != 0U)
716:         {
717:             status = HAL_PCD_EP_Flush(&s_pcd, ep);
718:             if (status != HAL_OK)
719:                 return Usb_HalResult(status);
720:         }
721: 
722:         //确认停止后按W1C应答旧事务；不清SETUP位或其他端点
723:         if ((ep & 0x80U) != 0U)
724:             USBx_INEP(0U)->DIEPINT = USB_OTG_DIEPINT_XFRC |
725:                 USB_OTG_DIEPINT_EPDISD | USB_OTG_DIEPINT_TOC;
726:         else
727:             USBx_OUTEP(0U)->DOEPINT = USB_OTG_DOEPINT_XFRC |
728:                 USB_OTG_DOEPINT_EPDISD;
729:         __DSB();
730:     }
731:     else
732:     {
733:         result = BSP_USB_AbortEp(ep);
734:         if (result != SYS_OK)
735:             return result;
736:     }
737:     status = HAL_PCD_EP_Close(&s_pcd, ep);
738:     if (status == HAL_OK)
739:     {
740:         entry->maxpacket = 0U;
741:         entry->is_stall = 0U;
742:         entry->xfer_buff = NULL;
743:         if ((ep & 0x80U) != 0U)
744:             memset(&s_tx_transfer[ep & 0x0FU], 0, sizeof(s_tx_transfer[0]));
745:         else
746:             s_rx_active[ep & 0x0FU] = false;
747:     }
748:     return Usb_HalResult(status);
749: }
750: //取消指定方向的传输；OUT只有在其他接收空闲时才清空共享RX FIFO
751: SysResult_t BSP_USB_AbortEp(uint8_t ep)
752: {
753:     HAL_StatusTypeDef status;
754:     uint8_t index;
755:     if (!s_ready || !Usb_ValidEp(ep) || (ep & 0x0FU) == 0U)
756:         return SYS_ERR_INVALID_ARG;
757:     index = ep & 0x0FU;
758:     if (Usb_BulkEndpoint(ep))
759:         return s_bulk_in[index].fenced || s_bulk_in[index].proof.source_owned ||
760:                s_bulk_in[index].proof.pool_owned ? SYS_ERR_BUSY : SYS_OK;
761:     if (s_bulk_fifo_owner != 0U) return SYS_ERR_BUSY;
762:     if (Usb_PcdEp(ep)->maxpacket == 0U)
763:         return SYS_ERR_INVALID_STATE;
764:     if ((ep & 0x80U) == 0U && s_rx_active[index] && Usb_OtherRxActive(ep))
765:         return SYS_ERR_BUSY;
766:     status = HAL_PCD_EP_Abort(&s_pcd, ep);
767:     if (status != HAL_OK)
768:         return Usb_HalResult(status);
769:     if ((ep & 0x80U) != 0U || s_rx_active[index])
770:     {
771:         status = HAL_PCD_EP_Flush(&s_pcd, ep);
772:         if (status != HAL_OK)
773:             return Usb_HalResult(status);
774:     }
775:     if ((ep & 0x80U) != 0U)
776:     {
777:         uint32_t USBx_BASE = (uint32_t)s_pcd.Instance;
778: 
779:         //停止并清FIFO后只应答本端点旧事件，保留其他端点
780:         USBx_INEP(index)->DIEPINT = USB_OTG_DIEPINT_XFRC | USB_OTG_DIEPINT_EPDISD | USB_OTG_DIEPINT_TOC;
781:         s_pcd.IN_ep[index].is_iso_incomplete = 0U;
782:         __DSB();
783:         memset(&s_tx_transfer[index], 0, sizeof(s_tx_transfer[index]));
784:     }
785:     else
786:         s_rx_active[index] = false;
787:     return SYS_OK;
788: }
